function updateCollaborationMember(data,options){return mutate("collaboration",value=>{const id=String(options.id),reason=String(options.reason??"").trim(),changedBy=String(options["changed-by"]??"프로젝트 책임자").trim(),roles=[...new Set(array(options.role).map(item=>String(item).trim()).filter(Boolean))];if(!id.startsWith("HUM-"))throw new Error("참여자 ID는 HUM- 접두사를 사용해야 합니다");if(!reason||!changedBy)throw new Error("참여자 변경 사유와 기록자는 필수입니다");const working=structuredClone(value),from=working.policy.current_profile;working.participants??=[];let item=working.participants.find(row=>row.id===id);const timestamp=now();if(!item){if(options.status!=="active"||!String(options.name??"").trim()||!roles.length)throw new Error("새 참여자는 이름·역할과 active 상태가 필요합니다");item={id,name:String(options.name).trim(),roles,status:"active",joined_at:timestamp,left_at:null};working.participants.push(item);}else{if(options.name)item.name=String(options.name).trim();if(roles.length)item.roles=roles;item.status=options.status;item.left_at=options.status==="inactive"?timestamp:null;if(options.status==="active"&&!item.joined_at)item.joined_at=timestamp;}const active=working.participants.filter(row=>row.status==="active");if(!active.length)throw new Error("프로젝트 책임자를 포함한 활성 참여자가 최소 1명 필요합니다");if(!active.some(row=>(row.roles??[]).includes("소유자")))throw new Error("활성 참여자 중 최소 1명은 소유자 역할이어야 합니다");refreshProfile(working);if(working.policy.current_profile==="CBP-TEAM"&&!active.some(row=>(row.roles??[]).includes("PM")))throw new Error("팀 프로필로 전환하려면 활성 참여자 중 최소 1명에게 PM 역할을 지정해야 합니다.");working.transitions??=[];working.transitions.push({id:nextId(working.transitions,"CBT"),from,to:working.policy.current_profile,reason,changed_at:timestamp,changed_by:changedBy,participant:id,participant_status:options.status});replaceObject(value,working);return `${id}을(를) ${options.status} 상태로 기록하고 협업 프로필을 ${working.policy.current_profile}(으)로 적용했습니다.`;});}
