function completeMergeRecheck(data,options){const participants=new Set((data.collaboration.participants??[]).map(item=>item.id)),evidence=[...new Set(array(options.evidence))].sort(),knownEvidence=new Set((data.evidence.evidence??[]).map(item=>item.id)),unknown=evidence.filter(id=>!knownEvidence.has(id));if(!participants.has(options["reviewed-by"]))throw new Error(`알 수 없는 수행자: ${options["reviewed-by"]}`);if(unknown.length)throw new Error(`알 수 없는 증거: ${unknown.join(", ")}`);return mutate("merges",value=>{const item=(value.merges??[]).find(row=>row.id===options.merge);if(!item)throw new Error(`알 수 없는 병합 레코드: ${options.merge}`);const recheck=(item.rechecks??[]).find(row=>row.id===options.recheck);if(!recheck)throw new Error(`${item.id}에 ${options.recheck} 재검토가 없습니다`);if(recheck.type==="test"&&!evidence.length)throw new Error("재테스트 완료에는 EVD 증거를 하나 이상 연결해야 합니다");recheck.status="completed";recheck.reviewed_by=options["reviewed-by"];recheck.reviewed_at=now();recheck.result=options.result;recheck.evidence=evidence;return `Completed ${item.id}/${recheck.id}; reviewer, time, result, and evidence were recorded.`;});}
function evaluationPrompt(data,id){const scenario=(data.evaluations.scenarios??[]).find(item=>item.id===id);if(!scenario)throw new Error(`알 수 없는 평가 시나리오: ${id}`);const fixturePath=resolve(ROOT,scenario.fixture),relativeFixture=relative(ROOT,fixturePath);if(relativeFixture.startsWith("..")||isAbsolute(relativeFixture))throw new Error("평가 fixture가 프로젝트 루트를 벗어납니다");const fixture=readFileSync(fixturePath,"utf8").trim();return `# ${scenario.id} — ${scenario.title}\n\n${fixture}\n\n## 기대 행동\n\n${(scenario.expected_behaviors??[]).map(item=>`- ${item}`).join("\n")}\n\n## 금지 행동\n\n${(scenario.forbidden_behaviors??[]).map(item=>`- ${item}`).join("\n")}\n\n## 평가 루브릭\n\n${(scenario.rubric??[]).map(item=>`- ${item}`).join("\n")}\n\n정본 규칙을 따라 요청을 처리하고, 최종 응답과 생성·수정한 산출물을 평가자가 검토할 수 있게 남기세요.`;}
